        <h2 id="stage-title">0단계: 대지·매스 기본</h2>
        <p id="stage-desc">대지 윤곽 안에 들어가는 가장 단순한 저층 매스를 배치합니다.</p>
        <p class="note">※ 공개 자료를 바탕으로 한 설명용 개념 재구성입니다. 실제 시공 도면·구조 설계가 아니며, 치수·단면은 추정값입니다.</p>
        <p class="legend-sources">기준 자료: 높이 555m, 지상 123층 (공개 정보). 설계: KPF (kpf.com) · 구조: LERA (lera.com)</p>
      </div>
    </div>
  </main>

  <footer>
    키보드: Tab으로 버튼 이동, Enter/Space로 선택 · 마우스/터치로 3D 모델 드래그 회전, 휠/핀치로 확대·축소 · claude-sonnet-5 생성
  </footer>
</div>

<script src="../runtime/three-runtime.js"></script>
<script>
(function(){
  "use strict";

  // ---------- 데이터 ----------
  var STAGES = [
    { name:"0. 대지·매스 기본",
      title:"0단계: 대지·매스 기본",
      desc:"대지 경계 안에 들어가는 단순 저층 매스를 가정합니다. 아직 테이퍼링이나 곡선은 없습니다." },
    { name:"1. 각진 매스 설정",
      title:"1단계: 각진 매스 설정",
      desc:"기준층 평면을 8각 형태로 단순화하고, 전체 높이에 걸쳐 균일한 각진 매스를 세웁니다." },
    { name:"2. 모서리 테이퍼링",
      title:"2단계: 모서리 테이퍼링",
      desc:"위로 올라갈수록 기준층 면적과 외곽선이 점진적으로 좁아지도록 각 층 반경을 줄여갑니다." },
    { name:"3. 곡선 실루엣 (도자기 선)",
      title:"3단계: 곡선 실루엣 적용",
      desc:"KPF가 언급한 한국 도자기 선을 참고하여, 테이퍼링 윤곽을 부드러운 S자 곡선으로 다듭듬습니다(개념적 재구성)." },
    { name:"4. 첨탑·스파이어 완성",
      title:"4단계: 첨탑·스파이어 완성",
      desc:"상부 첨탑(스파이어)과 전체 매스를 결합해 555m, 123층 개념의 완성형 실루엣을 구성합니다." }
  ];

  var DRAWINGS = {
    site: {
      title:"배치도 (Site Plan)",
      desc:"대지 안에서 타워 매스의 위치와 저층부 포디움 범위를 보여주는 개념도입니다. 단위: m (추정 대지 치수).",
      svg: siteSVG
    },
    floor: {
      title:"기준층 평면도 (Typical Floor Plan)",
      desc:"고층부 기준층의 개념적 평면 형태입니다. 중심 코어와 외곽 다각형 윤곽을 표시합니다. 단위: m (추정).",
      svg: floorSVG
    },
    elev: {
      title:"입면도 (Elevation)",
      desc:"지상에서 첨탑까지의 전체 높이 555m를 기준으로, 위로 갈수록 좁아지는 외곽선을 보여주는 개념 입면입니다.",
      svg: elevSVG
    },
    section: {
      title:"단면도 (Section)",
      desc:"건물을 수직으로 자른 개념 단면으로, 중심 코어와 외피 사이 공간 분포를 단순화해 표시합니다. 치수는 추정치입니다.",
      svg: sectionSVG
    }
  };

  function svgWrap(inner, vb){
    return '<svg class="plan" viewBox="'+vb+'" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="도면">' + inner + '</svg>';
  }

  function siteSVG(){
    return svgWrap(
      '<rect x="10" y="10" width="380" height="280" fill="none" stroke="#2a3142" stroke-width="1"/>' +
      '<polygon class="plan-outline" points="150,80 250,80 280,150 250,220 150,220 120,150" />' +
      '<circle cx="200" cy="150" r="6" fill="#d9a24b"/>' +
      '<line class="plan-dim" x1="150" y1="60" x2="250" y2="60"/>' +
      '<text class="plan-label" x="180" y="52">약 100m (대지 폭, 추정)</text>' +
      '<text class="plan-label" x="20" y="24">배치도 — 대지 경계와 타워 매스 위치(개념)</text>' +
      '<text class="plan-label" x="20" y="270">단위: m (공개 자료 기반 추정치)</text>',
      "0 0 400 300");
  }

  function floorSVG(){
    return svgWrap(
      '<polygon class="plan-outline" points="200,40 300,90 300,210 200,260 100,210 100,90" />' +
      '<rect x="170" y="130" width="60" height="40" fill="none" stroke="#8e9ab0" stroke-width="1"/>' +
      '<text class="plan-label" x="178" y="153">코어</text>' +
      '<line class="plan-dim" x1="100" y1="280" x2="300" y2="280"/>' +
      '<text class="plan-label" x="160" y="296">약 55m (기준층 외곽 폭, 추정)</text>' +
      '<text class="plan-label" x="10" y="24">기준층 평면도 — 다각형 외곽 + 중심 코어(개념)</text>',
      "0 0 400 320");
  }

  function elevSVG(){
    var html = '<text class="plan-label" x="10" y="20">입면도 — 지상에서 첨탑까지(개념, 555m 기준)</text>';
    var baseY = 280, topY = 20, cx = 200;
    var n = 12;
    var pathL = [], pathR = [];
    for(var i=0;i<=n;i++){
      var t = i/n;
      var y = baseY - t*(baseY-topY);
      var width = 90*(1-0.65*Math.pow(t,1.3)) ;
      if(t>0.9) width *= 0.35; // spire
      pathL.push((cx-width).toFixed(1)+","+y.toFixed(1));
      pathR.push((cx+width).toFixed(1)+","+y.toFixed(1));
    }
    var pts = pathL.concat(pathR.reverse()).join(" ");
    html += '<polygon class="plan-outline" points="'+pts+'" />';
    html += '<line class="plan-dim" x1="330" y1="280" x2="330" y2="20"/>';
    html += '<text class="plan-label" x="335" y="25">0m</text>';
    html += '<text class="plan-label" x="335" y="155">약 300m</text>';
    html += '<text class="plan-label" x="335" y="278">555m (전체, 공개 수치)</text>';
    html += '<text class="plan-label" x="10" y="296">실루엣은 공개 수치 기반 개념 재구성이며 실제 외피 상세와 다릅니다.</text>';
    return svgWrap(html, "0 0 400 320");
  }

  function sectionSVG(){
    var html = '<text class="plan-label" x="10" y="20">단면도 — 수직 단면 개념(코어/외피 분포, 추정)</text>';
    var baseY = 280, topY = 20, cx = 200;
    var n = 12;
    var pathL = [], pathR = [];
    for(var i=0;i<=n;i++){
      var t = i/n;
      var y = baseY - t*(baseY-topY);
      var width = 90*(1-0.65*Math.pow(t,1.3));
      if(t>0.9) width *= 0.35;
      pathL.push((cx-width).toFixed(1)+","+y.toFixed(1));
      pathR.push((cx+width).toFixed(1)+","+y.toFixed(1));
    }
    var pts = pathL.concat(pathR.reverse()).join(" ");
    html += '<polygon class="plan-outline" points="'+pts+'" fill="none" />';
    html += '<line x1="200" y1="280" x2="200" y2="20" stroke="#8e9ab0" stroke-width="6" stroke-dasharray="2,4"/>';
    html += '<text class="plan-label" x="206" y="150">코어(개념)</text>';
    html += '<text class="plan-label" x="10" y="296">실제 구조 체계(LERA)와 다른 단순화된 개념 단면입니다.</text>';
    return svgWrap(html, "0 0 400 320");
  }

  // ---------- 도면 UI ----------
  var currentDraw = "site";
  function renderDraw(){
    var d = DRAWINGS[currentDraw];
    document.getElementById("drawing-view").innerHTML = d.svg();
    document.getElementById("draw-info").innerHTML =
      '<h2>'+d.title+'</h2><p>'+d.desc+'</p>' +
      '<p class="note">선택한 단계와 완성 모델의 전체 실루엣이 함께 대응합니다. 상단 단계 버튼으로 전환해 보세요.</p>' +
      '<p class="legend-sources">출처(텍스트): KPF kpf.com/project/lotte-world-tower · LERA lera.com/lotte-world-tower</p>';
  }
  Array.prototype.forEach.call(document.querySelectorAll('#drawing-tabs button'), function(btn){
    btn.addEventListener('click', function(){
      Array.prototype.forEach.call(document.querySelectorAll('#drawing-tabs button'), function(b){b.classList.remove('active');});
      btn.classList.add('active');
      currentDraw = btn.getAttribute('data-draw');
      renderDraw();
    });
  });
  renderDraw();

  // ---------- Three.js 뷰어 ----------
  var viewerEl = document.getElementById('viewer');
  var renderer = new THREE.WebGLRenderer({antialias:true});
  renderer.setPixelRatio(Math.min(window.devicePixelRatio||1, 2));
  viewerEl.appendChild(renderer.domElement);

  var scene = new THREE.Scene();
  scene.background = new THREE.Color(0x070a10);

  var camera = new THREE.PerspectiveCamera(45, 1, 0.1, 5000);
  camera.position.set(220, 180, 220);

  var controls = new THREE.OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.minDistance = 60;
  controls.maxDistance = 900;
  controls.target.set(0, 90, 0);

  var hemi = new THREE.HemisphereLight(0xaabbdd, 0x111318, 0.9);
  scene.add(hemi);
  var dir = new THREE.DirectionalLight(0xffe9c7, 1.1);
  dir.position.set(150, 300, 100);
  scene.add(dir);

  var grid = new THREE.GridHelper(400, 20, 0x2a3142, 0x1a1f2c);
  grid.position.y = 0;
  scene.add(grid);

  var buildingGroup = new THREE.Group();
  scene.add(buildingGroup);
  var wireframe = false;

  function makeStageMesh(stageIdx){
    var group = new THREE.Group();
    var levels = 16;
    var totalHeight = 160; // 시각 스케일(실제 555m 비례 개념)
    var baseR = 55;

    var color = new THREE.Color(0xcccccc);
    var mat = new THREE.MeshStandardMaterial({
      color: 0x8893a8, metalness:0.3, roughness:0.55,
      wireframe: wireframe
    });

    if(stageIdx === 0){
      // 단순 저층 매스
      var geo = new THREE.BoxGeometry(baseR*1.4, 40, baseR*1.4);
      var mesh = new THREE.Mesh(geo, mat);
      mesh.position.y = 20;
      group.add(mesh);
      return group;
    }

    for(var i=0;i<levels;i++){
      var t0 = i/levels, t1 = (i+1)/levels;
      var h = totalHeight/levels;
      var y = t0*totalHeight + h/2;

      var r0, r1, sides;
      sides = (stageIdx>=1) ? 8 : 16;

      if(stageIdx === 1){
        r0 = baseR; r1 = baseR; // 균일 각진 매스
      } else if(stageIdx === 2){
        r0 = baseR*(1 - 0.55*Math.pow(t0,1.3));
        r1 = baseR*(1 - 0.55*Math.pow(t1,1.3));
      } else if(stageIdx === 3){
        var curve0 = 0.55*Math.pow(t0,1.1) + 0.05*Math.sin(t0*Math.PI*2)*0.5;
        var curve1 = 0.55*Math.pow(t1,1.1) + 0.05*Math.sin(t1*Math.PI*2)*0.5;
        r0 = baseR*(1 - curve0);
        r1 = baseR*(1 - curve1);
        sides = 16;
      } else { // stage 4 완성
        var c0 = 0.6*Math.pow(t0,1.2) + 0.04*Math.sin(t0*Math.PI*3);
        var c1 = 0.6*Math.pow(t1,1.2) + 0.04*Math.sin(t1*Math.PI*3);
        r0 = Math.max(2, baseR*(1-c0));
        r1 = Math.max(2, baseR*(1-c1));
        sides = 16;
      }
      r0 = Math.max(2, r0); r1 = Math.max(2, r1);

      var geo = new THREE.CylinderGeometry(r1, r0, h, sides, 1);
      var levelColor = new THREE.Color().lerpColors(
        new THREE.Color(0x5a6a8c), new THREE.Color(0xd9c89a), t0);
      var levelMat = new THREE.MeshStandardMaterial({
        color: levelColor, metalness:0.35, roughness:0.5, wireframe: wireframe
      });
      var mesh = new THREE.Mesh(geo, levelMat);
      mesh.position.y = y;
      group.add(mesh);
    }

    if(stageIdx === 4){
      var spireGeo = new THREE.ConeGeometry(4, 36, 10);
      var spireMat = new THREE.MeshStandardMaterial({color:0xf0e6c8, metalness:0.6, roughness:0.3, wireframe:wireframe});
      var spire = new THREE.Mesh(spireGeo, spireMat);
      spire.position.y = totalHeight + 18;
      group.add(spire);
    }

    return group;
  }

  function setStage(idx){
    while(buildingGroup.children.length){
      buildingGroup.remove(buildingGroup.children[0]);
    }
    var mesh = makeStageMesh(idx);
    buildingGroup.add(mesh);
    document.getElementById('hud-stage').textContent = STAGES[idx].name;
    document.getElementById('stage-title').textContent = STAGES[idx].title;
    document.getElementById('stage-desc').textContent = STAGES[idx].desc;
  }

  var stageBtns = document.querySelectorAll('#stage-bar button');
  Array.prototype.forEach.call(stageBtns, function(btn){
    btn.addEventListener('click', function(){
      Array.prototype.forEach.call(stageBtns, function(b){b.classList.remove('active');});
      btn.classList.add('active');
      setStage(parseInt(btn.getAttribute('data-stage'),10));
    });
    btn.addEventListener('keydown', function(e){
      if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); btn.click(); }
    });
  });

  setStage(0);

  document.getElementById('btn-reset').addEventListener('click', function(){
    camera.position.set(220, 180, 220);
    controls.target.set(0, 90, 0);
    controls.update();
  });

  document.getElementById('btn-wire').addEventListener('click', function(e){
    wireframe = !wireframe;
    e.target.classList.toggle('active', wireframe);
    buildingGroup.traverse(function(obj){
      if(obj.isMesh){ obj.material.wireframe = wireframe; }
    });
  });

  var autoRotate = false;
  document.getElementById('btn-auto').addEventListener('click', function(e){
    autoRotate = !autoRotate;
    e.target.classList.toggle('active', autoRotate);
    controls.autoRotate = autoRotate;
    controls.autoRotateSpeed = 1.2;
  });

  function resize(){
    var w = viewerEl.clientWidth, h = viewerEl.clientHeight;
    if(w<=0||h<=0) return;
    renderer.setSize(w, h);
    camera.aspect = w/h;
    camera.updateProjectionMatrix();
  }
  window.addEventListener('resize', resize);
  resize();

  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function animate(){
    requestAnimationFrame(animate);
    controls.update();
    renderer.render(scene, camera);
  }
  animate();

  // keyboard nudge for accessibility (arrow keys rotate camera slightly)
  viewerEl.setAttribute('tabindex','0');
  viewerEl.addEventListener('keydown', function(e){
    var step = 0.1;
    if(e.key === 'ArrowLeft'){ controls.rotateLeft ? controls.rotateLeft(step) : null; }
  });

})();
</script>
</body>
</html>
